<?php
namespace App\Domain\Clients; use App\Domain\PublicChrome\{PublicAssetPath,PublicLink}; use App\Models\Client; use Illuminate\Support\Facades\Cache; use Throwable; final class ClientViewData { public function published(string $slug):?array{try{$item=Client::publiclyVisible()->where('slug',$slug)->first();if(!$item)return null;return Cache::remember('public.clients.v1.'.$item->id.'.'.ClientCache::version($item->id),now()->addMinutes(15),fn()=>$this->transform($this->load($item),false));}catch(Throwable){return null;}} public function preview(Client $item):array{return $this->transform($this->load($item),true);} private function load(Client $item):Client{return $item->load(['industry','relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedCapabilities'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);} private function transform(Client $item,bool $preview):array{return ['name'=>$item->name,'slug'=>$item->slug,'type'=>$item->client_type,'description'=>$item->short_description,'logo'=>PublicAssetPath::isSafe($item->logo_path)?$item->logo_path:null,'logo_alt'=>$item->logo_alt,'website_url'=>PublicLink::isSafeUrl($item->website_url)?$item->website_url:null,'country_code'=>$item->country_code,'industry'=>$item->industry&&!$item->industry->archived_at?$item->industry->title:null,'meta_title'=>$item->meta_title?:$item->name,'meta_description'=>$item->meta_description?:$item->short_description,'canonical_url'=>$item->canonical_url,'robots'=>$preview?'noindex, nofollow':(($item->robots_index?'index':'noindex').', '.($item->robots_follow?'follow':'nofollow')),'relations'=>['solutions'=>$item->relatedSolutions->map(fn($x)=>['title'=>$x->title,'url'=>route('solutions.show',$x->slug)])->all(),'products'=>$item->relatedProducts->map(fn($x)=>['title'=>$x->title,'url'=>route('products.show',$x->slug)])->all(),'capabilities'=>$item->relatedCapabilities->map(fn($x)=>['title'=>$x->title,'url'=>route('capabilities.show',$x->slug)])->all(),'pages'=>$item->relatedPages->map(fn($x)=>['title'=>$x->title,'url'=>route('pages.show',$x->slug)])->all()]];} }
